function map<T, U>(items: readonly T[], fn: (item: T, index: number) => U): U[] {
  const result: U[] = [];
  for (let i = 0; i < items.length; i++) {
    result.push(fn(items[i], i));
  }
  return result;
}

const lengths = map(['a', 'bb'], (s) => s.length); // number[]

type Next = () => void;
type Request = { path: string };
type Response = { status: (code: number) => Response };
type Middleware = (req: Request, res: Response, next: Next) => void;

function compose(...middleware: Middleware[]): Middleware {
  return (req, res, next) => {
    let i = 0;
    const run = () => middleware[i++]?.(req, res, run) ?? next();
    run();
  };
}

function debounce<T extends (...args: never[]) => void>(
  fn: T,
  ms: number
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout>;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

const search = debounce((q: string) => console.log(q), 300);

function forEach(arr: unknown[], cb: Function) {
  arr.forEach(cb); // cb could be anything
}

